/* ---------- Onda 4d: Cadastros: Unidades, Usuários, Perfis, Bancadas, Exames, Componentes, Perguntas, Observações, Variáveis, Etiquetas ----------
   Padrão transversal das abas de cadastro: lista só com ativos (D3), código único por laboratório (D2), 10 por página, "i" em cada configuração. */
const filtroSit=(v,oc)=>`<select class="in" style="width:auto" onchange="${oc}" aria-label="Situação"><option value="ativo" ${v==='ativo'?'selected':''}>Ativos</option><option value="off" ${v==='off'?'selected':''}>Desativados</option><option value="all" ${v==='all'?'selected':''}>Todos</option></select>`;
const rodape=(n,t)=>`<div class="tfoot"><span>Mostrando 1-${n} de ${t} · 10 por página no servidor</span><div class="pager"><button aria-label="Anterior">‹</button><button class="cur">1</button>${t>10?'<button>2</button>':''}<button aria-label="Próxima">›</button></div></div>`;
const sitBadge=on=>`<span class="badge ${on?'ok':'neutral'}">${on?'Ativo':'Desativado'}</span>`;
const acoesCad=(on,fnEd,fnVer,fnOff)=>`<span class="row" style="gap:4px;flex-wrap:nowrap"><button class="ibtn sm plain" ${tipAttr('Editar','Abre o cadastro para alterar.')} onclick="event.stopPropagation();${fnEd}">${I.edit}</button><button class="ibtn sm plain" ${tipAttr('Visualizar','Abre só para leitura.')} onclick="event.stopPropagation();${fnVer}"><svg class="i" viewBox="0 0 24 24"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></button><button class="ibtn sm plain" ${tipAttr(on?'Desativar':'Ativar',on?'Desativar pede confirmação e checa vínculos.':'Reativar não mexe em nada ligado.')} onclick="event.stopPropagation();${fnOff}">${on?I.x:I.check}</button></span>`;

/* ===== Unidades (aba Unidades e tabelas de preço) ===== */
const UNIDADES=[{c:10,n:'Unidade 10 · Central (matriz)',tipo:'Unidade própria',cnpj:'00.000.000/0001-00',cnes:'1234567',lic:'15/03/2027',cor:'#27847D',at:true,col:true,proc:true,fat:true,sit:true},{c:12,n:'Posto 12 · Messejana',tipo:'Unidade própria',cnpj:'(usa o da matriz)',cnes:'1234568',lic:'08/11/2026',cor:'#2979FF',at:true,col:true,proc:false,fat:false,sit:true},{c:14,n:'Posto 14 · Aldeota',tipo:'Unidade própria',cnpj:'(usa o da matriz)',cnes:'1234569',lic:'30/06/2027',cor:'#F08C2E',at:true,col:true,proc:false,fat:true,sit:true},{c:'B2B',n:'Clínica Vida Plena (Clínicas)',tipo:'Parceiro B2B · clínica',cnpj:'11.111.111/0001-11',cnes:'—',lic:'—',cor:'#7C4DFF',at:false,col:true,proc:false,fat:false,sit:true},{c:'B2B',n:'Mineradora Vale Verde (empresa)',tipo:'Parceiro B2B · empresa',cnpj:'22.222.222/0001-22',cnes:'—',lic:'—',cor:'#E91E8C',at:false,col:false,proc:false,fat:false,sit:true},{c:'AP',n:'Pardini',tipo:'Laboratório de apoio',cnpj:'33.333.333/0001-33',cnes:'—',lic:'—',cor:'#3DA98F',at:false,col:false,proc:true,fat:false,sit:true},{c:'AP',n:'DB Diagnósticos',tipo:'Laboratório de apoio',cnpj:'44.444.444/0001-44',cnes:'—',lic:'—',cor:'#2ECC71',at:false,col:false,proc:true,fat:false,sit:true},{c:11,n:'Posto 11 · Centro (fechado)',tipo:'Unidade própria',cnpj:'',cnes:'',lic:'',cor:'#78909C',at:false,col:false,proc:false,fat:false,sit:false}];
let UN_SIT='ativo';
VIEWS.unidades=()=>{const l=UNIDADES.filter(u=>UN_SIT==='all'||(UN_SIT==='off'?!u.sit:u.sit));
 return `${pageHead('Cadastros','Unidades','Unidades próprias, parceiros B2B e laboratórios de apoio, com as quatro chaves (atende, coleta, processa, fatura). Dados de exemplo.',`${rulesBtn('Unidades')}<button class="btn" onclick="unForm()" ${tipAttr('Nova unidade','Tipo, dados básicos, CNPJ (opcional na própria), CNES, licença com validade e aviso 60 dias antes, cor, horários, salas de coleta e laudo próprio.')}>${I.plus} Nova unidade</button>`)}
<div class="filters"><div class="inwrap" style="flex:1 1 220px">${LUPA}<input class="in" placeholder="Nome, CNPJ ou código"></div>${filtroSit(UN_SIT,"UN_SIT=this.value;reView()")}<select class="in" style="width:auto"><option>Todos os tipos</option><option>Unidade própria</option><option>Parceiro B2B</option><option>Laboratório de apoio</option></select></div>
<div class="alert warn"><span><b>Licença do Posto 12 vence em 10 dias (08/11).</b> Aviso automático 60 dias antes; o administrador recebe na Home.</span></div>
${tabela(['Unidade','Tipo','CNPJ e CNES','Licença','Chaves','Situação',''],l.map(u=>`<tr style="cursor:pointer" onclick="unForm(${UNIDADES.indexOf(u)},true)">${td('Unidade',`<span class="cor" style="background:${u.cor}"></span>${esc(u.n)}${typeof u.c==='number'?` <small class="tl">· código ${u.c} no tubo</small>`:''}`)}${td('Tipo',u.tipo)}${td('CNPJ e CNES',`<div class="two"><span class="mono">${u.cnpj||'—'}</span><small>CNES ${u.cnes||'—'}</small></div>`)}${td('Licença',u.lic==='08/11/2026'?`<span class="prazo-warn">${u.lic}</span>`:u.lic||'—')}${td('Chaves',[['atende',u.at],['coleta',u.col],['processa',u.proc],['fatura',u.fat]].map(([k,v])=>`<span class="badge ${v?'acc':'neutral'}" style="height:22px;font-size:11px;margin:1px">${k}</span>`).join(''))}${td('Situação',sitBadge(u.sit))}${td('',acoesCad(u.sit,`unForm(${UNIDADES.indexOf(u)})`,`unForm(${UNIDADES.indexOf(u)},true)`,`toast('${u.sit?'Desativar unidade: checa amostras pendentes e usuários ligados':'Unidade reativada'}')`))}</tr>`))}${rodape(l.length,l.length)}
${piada(41,{admin:'Unidade com quatro chaves: atende, coleta, processa, fatura. O Posto 12 tem duas e a certeza de que faz tudo.',gestor:'Posto que não processa não vê área técnica. Menos abas, menos culpa.',todos:'Toda unidade tem uma cor, sempre com o nome ao lado. Nada depende só da cor, nem o posto laranja.'})}`};
function unForm(i,ver){const u=UNIDADES[i]||{n:'',tipo:'Unidade própria',cnpj:'',cnes:'',lic:'',cor:'#27847D',at:true,col:true,proc:false,fat:false};const d=ver?'disabled':'';
 openModal(`${mh(i===undefined?'Nova unidade':(ver?'Unidade':'Editar unidade'))}<div class="mb"><div class="formgrid"><div class="field"><label>Tipo <span class="req">*</span> ${info('Unidade própria (central e postos), Parceiro B2B (clínica, empresa, hospital ou laboratório que manda pedidos) ou Laboratório de apoio.')}</label><select class="in" ${d}><option ${u.tipo.startsWith('Unidade')?'selected':''}>Unidade própria</option><option ${u.tipo.startsWith('Parceiro')?'selected':''}>Parceiro B2B</option><option ${u.tipo.startsWith('Lab')?'selected':''}>Laboratório de apoio</option></select></div><div class="field"><label>Nome <span class="req">*</span></label><input class="in" value="${esc(u.n)}" ${d}></div><div class="field"><label>CNPJ ${info('Opcional na unidade própria (vazio usa o da matriz no laudo e no fiscal); obrigatório em parceiro B2B e apoio.')}</label><input class="in" value="${esc(u.cnpj)}" ${d}></div><div class="field"><label>CNES</label><input class="in" value="${u.cnes||''}" ${d}></div><div class="field"><label>Licença sanitária · validade ${info('Aviso 60 dias antes, quando ligado.')}</label><input class="in" value="${u.lic||''}" ${d}></div><div class="field"><label>Cor da unidade ${info('Sempre com o nome ou a sigla ao lado.')}</label><input class="in" type="color" value="${u.cor}" ${d}></div><div class="field"><label>Código no tubo ${info('Primeiro bloco do código do tubo (D21), de 10 a 99.')}</label><input class="in" value="${typeof u.c==='number'?u.c:''}" ${d}></div><div class="field"><label>Horário limite de envio ao central</label><input class="in" value="14:30" ${d}></div><div class="field"><label>Acréscimo de prazo · rotina / urgência</label><input class="in" value="1 dia útil / 0" ${d}></div><div class="field"><label>Convênio e plano padrão</label><input class="in" value="Unimed Fortaleza · Básico" ${d}></div></div>
<h4 style="margin-top:12px">Chaves da unidade ${info('Independentes: a unidade muda de papel sem recadastrar.')}</h4><div class="row">${[['atende',u.at],['coleta',u.col],['processa (bancadas)',u.proc],['fatura',u.fat]].map(([k,v])=>`<label class="switch"><input type="checkbox" ${v?'checked':''} ${d}><span class="tr"></span>${k}</label>`).join('')}</div>
<h4 style="margin-top:12px">Salas de coleta e impressoras</h4><div class="at-list"><div class="at-row"><div class="grow">Box 1<small>Zebra ZD230 · etiqueta padrão 40 × 20</small></div></div><div class="at-row"><div class="grow">Box 2<small>Zebra ZD230</small></div></div></div>
<h4 style="margin-top:12px">Laudo desta unidade</h4><p class="tl">Logomarca e rodapé livre próprios (opcional); versão de impressão: preto e branco.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">${ver?'Fechar':'Cancelar'}</button>${ver?'':`<button class="btn" onclick="closeModal();retorno('ok','Unidade salva','Horário de funcionamento, feriados locais e tabela de preço podem ser ajustados na ficha.')">Salvar</button>`}</div>`)}
GUIDES.unidades=['A lista abre com as unidades ativas: próprias, parceiros B2B e apoio.','Cada unidade tem quatro chaves independentes: atende, coleta, processa e fatura.','Licença e CNES com validade avisam 60 dias antes; a cor sempre vem com o nome.'];
REGRAS['Unidades']={aba:'Unidades e tabelas de preço',itens:[['Tipos','Unidade própria (salas de coleta, caixa, código no tubo, acréscimos de prazo); Parceiro B2B (tabela de repasse, fatura, Clínicas); Laboratório de apoio (códigos de integração, tabela de custo).'],['CNPJ','Opcional na própria (vazio usa o da matriz); obrigatório em B2B e apoio.'],['Chaves','Atende, coleta, processa e fatura, independentes (B15); código de unidade da etiqueta de 10 a 99.'],['Ajustes','Horário limite de envio ao central, convênio e plano padrão, cor com nome, horário de funcionamento com feriados locais, acréscimos de prazo, salas com impressora.'],['Licença','CNES e licença sanitária com validade e aviso 60 dias antes.'],['Laudo','Unidade própria e parceiro B2B podem ter logomarca e rodapé próprios; o resto é fixo.']]};

/* ===== Usuários (aba Usuários: cadastro, link de cadastro 7 dias, unidades, bancadas, conselho, 2º fator) ===== */
let US_SIT='ativo',US_Q='';
VIEWS.usuarios=()=>{const l=USUARIOS.filter(u=>(US_SIT==='all'||(US_SIT==='off'?u.sit!=='Ativo':u.sit==='Ativo'))&&(!US_Q||semAc(u.n).includes(semAc(US_Q))));
 return `${pageHead('Cadastros','Usuários','Quem acessa a clínica (todas as unidades e módulos): perfil, unidades, bancadas, conselho e segundo fator. A senha é criada pela própria pessoa. Dados de exemplo.',`${rulesBtn('Usuários')}<button class="btn sec" onclick="usLink()" ${tipAttr('Link de cadastro','Gera link com o perfil escolhido; vale 7 dias e uma vez; a conta só ativa depois da aprovação.')}>Gerar link de cadastro</button><button class="btn" onclick="usForm()" ${tipAttr('Cadastrar usuário','Nome, CPF, e-mail, telefone, perfil e unidades; conselho para quem libera.')}>${I.plus} Cadastrar usuário</button>`)}
<div class="filters"><div class="inwrap" style="flex:1 1 220px">${LUPA}<input class="in" placeholder="Nome" value="${esc(US_Q)}" oninput="US_Q=this.value;reView();setTimeout(()=>{const i=document.querySelector('.filters input');if(i){i.focus();i.setSelectionRange(99,99)}},0)"></div>${filtroSit(US_SIT,"US_SIT=this.value;reView()")}<select class="in" style="width:auto"><option>Todos os perfis</option>${PERFIS.map(p=>`<option>${p[1]}</option>`).join('')}</select></div>
${tabela(['Usuário','Perfil','Unidades','Bancadas','Conselho','Situação',''],l.map(u=>`<tr style="cursor:pointer" onclick="usForm(${USUARIOS.indexOf(u)},true)">${td('Usuário',`<div class="cx-user"><span class="avatar">${u.ini}</span><div class="two">${esc(u.n)}<small>${u.email}</small></div></div>`)}${td('Perfil',nomePerfil(u.perfil))}${td('Unidades',u.unids.length===3?'todas':u.unids.map(x=>x===10?'Central':'Posto '+x).join(', '))}${td('Bancadas',u.banc?u.banc.map(b=>BANCADAS.find(x=>x.c===b).n).join(', '):'todas')}${td('Conselho',u.cons||'—')}${td('Situação',`<span class="badge ${u.sit==='Ativo'?'ok':u.sit==='Inativo'?'neutral':'warn'}">${u.sit}</span>`)}${td('',u.sit==='Pendente de Ativação'?`<button class="btn sm" onclick="event.stopPropagation();toast('Cadastro aprovado; a pessoa já entra com a senha que criou')">Aprovar</button>`:acoesCad(u.sit==='Ativo',`usForm(${USUARIOS.indexOf(u)})`,`usForm(${USUARIOS.indexOf(u)},true)`,`toast('${u.sit==='Ativo'?'Usuário desativado: perde o acesso na hora':'Usuário reativado'}')`))}</tr>`))}${rodape(l.length,l.length)}
${piada(42,{admin:'Link de cadastro vale 7 dias e uma vez. Igual promessa de dieta, só que o sistema cumpre.',todos:'O operador não define senha. Quem define é a pessoa. Quem esquece também.'})}`};
function usForm(i,ver){const u=USUARIOS[i]||{n:'',email:'',perfil:'recepcao',unids:[10],cons:''};const d=ver?'disabled':'';
 openModal(`${mh(i===undefined?'Cadastrar usuário':(ver?esc(u.n):'Editar usuário'))}<div class="mb"><h4>Dados básicos</h4><div class="formgrid"><div class="field"><label>Nome completo <span class="req">*</span></label><input class="in" value="${esc(u.n)}" ${d}></div><div class="field"><label>CPF <span class="req">*</span> ${info('Único na plataforma (D1): um login por pessoa; ela escolhe a clínica ao entrar.')}</label><input class="in" value="${u.n?'***.***.***-**':''}" ${d} oninput="this.value=mCPF(this.value)"></div><div class="field"><label>E-mail <span class="req">*</span></label><input class="in" value="${u.email}" ${d}></div><div class="field"><label>Telefone <span class="req">*</span></label><input class="in" value="${u.n?'(85) 9****-****':''}" ${d}></div></div>
<h4 style="margin-top:12px">Perfil e permissões ${info('Selecionar o perfil carrega as permissões padrão; o que você mudar aqui fica como exceção do usuário.')}</h4><div class="row">${PERFIS.map(p=>`<label class="chip ${u.perfil===p[0]?'on':''}"><input type="radio" name="usp" hidden ${u.perfil===p[0]?'checked':''} ${d}>${p[1]}</label>`).join('')}</div>
<h4 style="margin-top:12px">Unidades e bancadas</h4><div class="row">${[10,12,14].map(x=>`<label class="check"><input type="checkbox" ${u.unids.includes(x)?'checked':''} ${d}>${unidNome(x).split(' · ')[0]}${x===10?' (padrão)':''}</label>`).join('')}</div><p class="tl">Quem tem mais de uma unidade vê tudo junto; a unidade atual vale só para impressora, caixa e novo atendimento. Bancadas: ${u.banc?u.banc.join(', '):'todas'}.</p>
<h4 style="margin-top:12px">Conselho e assinatura ${info('Obrigatórios para quem libera resultados; a forma de assinatura (ICP-Brasil em nuvem ou avançada) é escolha da clínica.')}</h4><div class="formgrid"><div class="field"><label>Conselho · número · UF</label><input class="in" value="${u.cons||''}" placeholder="Ex.: CRBM 1ª 12345" ${d}></div><div class="field"><label>Segundo fator ${info('Padrão vem do perfil (opcional nos 9 perfis padrão); o administrador ajusta por usuário.')}</label><select class="in" ${d}><option>Opcional (padrão do perfil)</option><option>Obrigatório · aplicativo</option><option>Obrigatório · SMS</option></select></div></div>
<p class="tl">Opcionais (no primeiro acesso ou depois): nome social, nascimento, RG, endereço, cargo, CBO e CNS (TISS), admissão, foto, imagem da assinatura, contato de emergência. Cada campo tem o "i" com a finalidade (LGPD).</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">${ver?'Fechar':'Cancelar'}</button>${ver?'':`<button class="btn" onclick="closeModal();retorno('ok','Usuário cadastrado','E-mail de ativação enviado: a pessoa cria a própria senha e, se exigido, o segundo fator.')">Cadastrar</button>`}</div>`)}
function usLink(){openModal(`${mh('Gerar link de cadastro')}<div class="mb"><div class="field"><label>Perfil do novo usuário</label><select class="in">${PERFIS.map(p=>`<option>${p[1]}</option>`).join('')}</select></div><div class="field"><label>Unidade padrão</label><select class="in"><option>Unidade 10 · Central</option><option>Posto 12</option><option>Posto 14</option></select></div><div class="alert info"><span>A pessoa preenche nome, CPF, e-mail e telefone, cria a senha e o segundo fator se exigido. O link vale 7 dias e uma vez; a conta só ativa depois da sua aprovação. Geração, uso e aprovação ficam na auditoria.</span></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Link gerado','deoclinic.com.br/cadastro/x7Q2… copiado. Mande por WhatsApp ou e-mail; vale até 05/11.')">Gerar e copiar</button></div>`)}
GUIDES.usuarios=['Cadastre com nome, CPF, e-mail, telefone, perfil e unidades; a pessoa cria a própria senha pelo e-mail de ativação.','Ou gere um link de cadastro com o perfil já escolhido; aprove quando a pessoa terminar.','Quem libera resultados precisa de conselho, número e UF.'];
REGRAS['Usuários']={aba:'Usuários',itens:[['D1','Um login por pessoa na plataforma; ela escolhe a clínica ao entrar; CPF e e-mail únicos; cada laboratório define o perfil dela e vê só os próprios dados.'],['Obrigatórios','Nome, CPF, e-mail, telefone, perfil e unidades; conselho, número e UF para quem libera.'],['Link de cadastro','Perfil escolhido pelo administrador; vale 7 dias e uma vez; conta ativa só após aprovação; tudo na auditoria.'],['Unidades','Uma ou mais; Administrador e Dr. podem ter todas; quem tem várias vê tudo junto; unidade atual só para impressora, caixa e novo atendimento.'],['Segundo fator','Configurável por usuário; padrão do perfil; no primeiro acesso já cadastra quando exigido.'],['Senha','O operador nunca define a senha; e-mail de ativação com link; reenvio quando falhar.']]};

/* ===== Perfis e permissões (aba Perfis: perfis padrão da plataforma, permissões por ação e escopo de unidade, avisos da Home) ===== */
/* 04/11 (crítica do Clinicas, T1 a T3): um modelo só de permissão, por AÇÃO, com ESCOPO DE UNIDADE, checado no servidor.
   Perfil → módulos → ações; o usuário herda e guarda só exceções. Vale para a clínica, o laboratório, a imagem, o hospital, o financeiro e o estoque. */
const PERM_MOD=['Clínica e configurações','Perfis e usuários','Unidades e tabelas de preço','Cadastros técnicos','Agenda','Fila e triagem','Atendimento e caixa','Prontuário','Imagem e laudos de imagem','Internação e centro cirúrgico','Coleta e transporte','Recebimento e recoleta','Mapa e digitação','Conferência e liberação','Microbiologia','Controle de qualidade','Gestão da qualidade','Soroteca','Laudos e entrega','Financeiro e convênios','Faturamento e TISS','Estoque','Dashboard','Relatórios e auditoria','Importação e integrações'];
const PERM_ACOES_PADRAO=['ver','incluir','alterar','desativar com motivo'];
const PERM_ACOES={'Clínica e configurações':['ver','alterar configurações','ligar e desligar módulos'],'Perfis e usuários':['ver','criar','editar','gestão de perfis (crítica)','autorizar suporte do DeoClinic'],'Cadastros técnicos':['ver','incluir','alterar','desativar com motivo','alterar preço e custo'],
 'Agenda':['ver','marcar','remarcar','registrar falta','encaixe fora da grade','overbooking','bloquear agenda'],'Fila e triagem':['ver','emitir senha','chamar','chamar fora da ordem','cancelar senha (com motivo)','triar'],
 'Atendimento e caixa':['ver','atender','orçar','receber','abrir e fechar caixa','sangria','estornar (com motivo)','desconto acima do limite','editar preço ao paciente','reabrir caixa','unificar pacientes'],
 'Prontuário':['ver','evoluir','prescrever','emitir atestado e documento','assinar','ver atendimento de outro profissional'],'Imagem e laudos de imagem':['ver','realizar exame','laudar','assinar laudo','retificar laudo'],
 'Internação e centro cirúrgico':['ver','admitir','transferir','dar alta','agendar cirurgia','checklist de cirurgia segura'],'Conferência e liberação':['ver','lançar','liberar e assinar (exige conselho)','recusar','desfazer','retificar'],
 'Financeiro e convênios':['ver','lançar conta','pagar','conciliar','ver DRE e margem'],'Faturamento e TISS':['ver','gerar e autorizar guia','fechar lote','recorrer glosa'],'Estoque':['ver','entrada','saída e baixa','transferência','ajuste de inventário','aprovar pedido de compra'],'Relatórios e auditoria':['ver','gerar','exportar (fica na auditoria)']};
const permAcoes=m=>PERM_ACOES[m]||PERM_ACOES_PADRAO;
const PERM_PERFIL={admin:PERM_MOD.filter(m=>m!=='Conferência e liberação'),
 gestor:['Unidades e tabelas de preço','Agenda','Fila e triagem','Atendimento e caixa','Coleta e transporte','Recebimento e recoleta','Estoque','Dashboard'],
 recepcao:['Agenda','Fila e triagem','Atendimento e caixa','Laudos e entrega'],
 medico:['Agenda','Prontuário','Laudos e entrega','Internação e centro cirúrgico','Dashboard'],
 enfermagem:['Agenda','Fila e triagem','Prontuário','Internação e centro cirúrgico','Estoque'],
 imagem:['Agenda','Imagem e laudos de imagem','Prontuário','Laudos e entrega'],
 coletador:['Coleta e transporte','Agenda'],tecnico:['Recebimento e recoleta','Mapa e digitação','Controle de qualidade','Soroteca','Microbiologia','Estoque'],
 dr:['Conferência e liberação','Mapa e digitação','Recebimento e recoleta','Microbiologia','Controle de qualidade','Soroteca','Laudos e entrega','Dashboard'],
 financeiro:['Financeiro e convênios','Atendimento e caixa','Faturamento e TISS','Dashboard','Relatórios e auditoria'],faturamento:['Faturamento e TISS','Financeiro e convênios','Cadastros técnicos','Dashboard'],convenios:['Financeiro e convênios','Faturamento e TISS','Dashboard'],
 estoque:['Estoque','Cadastros técnicos','Relatórios e auditoria'],qualidade:['Gestão da qualidade','Controle de qualidade','Dashboard','Relatórios e auditoria']};
/* Ações desligadas dentro de um módulo ligado (o resto do módulo vale) */
