function pfForm(id,ver){const n=id?nomePerfil(id):'';const on=id?(PERM_PERFIL[id]||[]):[];const d=ver?'disabled':'';PF_Q='';const esc0=id?PERM_ESCOPO[id]||'vinculadas':'vinculadas';
 openModal(`${mh(id?(ver?n:'Editar perfil · '+n):'Criar perfil')}<div class="mb"><div class="formgrid"><div class="field"><label>Nome do perfil <span class="req">*</span></label><input class="in" value="${n}" ${d}></div><div class="field"><label>Descrição</label><input class="in" placeholder="Opcional (até 500 caracteres)" ${d}></div><div class="field"><label>Segundo fator (padrão do perfil)</label><select class="in" ${d}><option>Opcional</option><option ${['admin','financeiro','dr'].includes(id)?'selected':''}>Obrigatório</option></select></div><div class="field"><label>Escopo de unidade <span class="req">*</span> ${info('Em quais unidades o perfil age. Toda consulta e toda ação são filtradas pela unidade no servidor, não só no menu (crítica do sistema antigo: filtro de unidade vindo da tela, vazio = todas).')}</label><select class="in" ${d}>${PERM_ESCOPOS.map(([k,t])=>`<option ${esc0===k?'selected':''}>${t}</option>`).join('')}</select></div></div>
<p class="tl">${(PERM_ESCOPOS.find(e=>e[0]===esc0)||[])[2]||''}. Escopo por módulo: o financeiro pode ver todas as unidades e o caixa só a da sessão; ajuste na linha do módulo.</p>
<h4 style="margin-top:12px">Permissões por ação ${info('Cada módulo tem as suas ações. Ligar o módulo liga as ações padrão do perfil; desmarque a ação que o perfil não faz. Toda ação é checada no servidor e vai para a auditoria.')}</h4><div class="inwrap" style="margin-bottom:8px">${LUPA}<input class="in" placeholder="Pesquise por um módulo ou uma ação" oninput="document.querySelectorAll('#pfPerm .perm').forEach(p=>p.hidden=!semAc(p.textContent).includes(semAc(this.value)))"></div>
<div id="pfPerm" style="max-height:340px;overflow:auto">${PERM_MOD.map(m=>{const ligado=on.includes(m);return `<div class="perm" style="flex-wrap:wrap;align-items:flex-start"><div style="flex:1 1 220px;min-width:0">${m}<div class="row" style="gap:4px 12px;margin-top:4px">${permAcoes(m).map(a=>`<label class="check" style="font-size:12.5px;color:var(--fg2)"><input type="checkbox" ${ligado&&permAcaoOn(id,m,a)?'checked':''} ${d}>${a}</label>`).join('')}</div></div><span class="row" style="gap:8px;flex-wrap:nowrap;align-items:center">${ligado?`<select class="in" style="width:auto;height:30px;font-size:12px" ${d} aria-label="Escopo de ${m}">${PERM_ESCOPOS.map(([k,t])=>`<option ${(m==='Atendimento e caixa'&&id==='financeiro'?'atual':esc0)===k?'selected':''}>${t}</option>`).join('')}</select>`:''}<label class="switch"><input type="checkbox" ${ligado?'checked':''} ${d}><span class="tr"></span></label></span></div>`}).join('')}</div>
${id?`<h4 style="margin-top:12px">Avisos da Home que este perfil recebe ${info('Cada clínica muda aqui.')}</h4><div class="row" style="gap:6px">${Object.entries(ROTA).filter(([k,v])=>v.includes(id)||id==='admin').map(([k])=>`<span class="badge neutral">${AVISO_NOME[k]||k}</span>`).join('')||'<span class="tl">nenhum</span>'}</div>`:''}</div><div class="mf"><button class="btn ghost" onclick="closeModal()">${ver?'Fechar':'Cancelar'}</button>${ver?`<button class="btn sec" onclick="pfForm('${id}')">Editar</button><button class="btn sec" onclick="closeModal();toast('Cópia criada: Perfil ${n} (cópia)')">Copiar perfil</button>`:`<button class="btn" onclick="closeModal();retorno('ok','Perfil salvo','A mudança vale para todos os usuários do perfil, menos nas exceções de cada um, e vai para a auditoria com antes e depois.')">Salvar</button>`}</div>`,'wide')}
GUIDES.perfis=['Os perfis padrão já vêm prontos (clínica, laboratório, imagem, hospital, financeiro e estoque); edite, copie ou crie outros.','Cada módulo tem ações próprias: desmarque a ação que o perfil não faz e escolha o escopo de unidade.','Desativar um perfil bloqueia na hora os usuários ligados; o último com Gestão de Perfis não pode ser desativado.'];
