function bcForm(c,ver){const b=BANCADAS.find(x=>x.c===c)||{c:'',n:'',setor:'Bioquímica',ordem:'',ex:[],ap:''};const d=ver?'disabled':'';
 openModal(`${mh(c?(ver?b.n:'Editar bancada'):'Cadastrar bancada')}<div class="mb"><div class="formgrid"><div class="field"><label>Código de identificação <span class="req">*</span> ${info('Único dentro do laboratório (D2).')}</label><input class="in" value="${b.c}" ${d}></div><div class="field"><label>Nome da bancada <span class="req">*</span></label><input class="in" value="${b.n}" ${d}></div><div class="field"><label>Setor <span class="req">*</span></label><select class="in" ${d}>${['Hematologia','Bioquímica','Imunologia e hormônios','Urinálise','Parasitologia','Microbiologia','Coagulação','Biologia molecular','Apoio'].map(s=>`<option ${b.setor===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Ordem de exibição no laudo ${info('Ordena as bancadas no laudo e quando vários mapas são impressos de uma vez; empate desempata por ordem alfabética.')}</label><input class="in" value="${b.ordem}" ${d}></div></div>
<div class="grid" style="grid-template-columns:1fr 1fr;margin-top:12px"><div><h4>Exames cadastrados</h4><div class="inwrap" style="margin-bottom:6px">${LUPA}<input class="in" placeholder="Pesquise por um exame cadastrado" ${d}></div><div class="at-list" style="max-height:180px;overflow:auto">${EXAMES.filter(e=>!b.ex.includes(e.c)&&!e.serv).slice(0,6).map(e=>`<div class="at-row" draggable="true"><div class="grow">${e.n}<small>${e.c}</small></div></div>`).join('')}</div></div><div><h4>Exames vinculados ${info('Arraste da esquerda; a ordem aqui é a ordem no mapa e no laudo.')}</h4><div class="at-list" style="max-height:220px;overflow:auto">${b.ex.length?b.ex.map(c=>`<div class="at-row" draggable="true"><div class="grow">${EX[c]?EX[c].n:c}<small>${c}</small></div>${ver?'':`<button class="ibtn sm plain" onclick="toast('Removido da bancada')">${I.x}</button>`}</div>`).join(''):'<div class="empty" style="padding:16px"><p>Nenhum exame adicionado. Segure e arraste o exame que deseja vincular à bancada.</p></div>'}</div></div></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">${ver?'Fechar':'Cancelar'}</button>${ver?'':`<button class="btn" onclick="closeModal();retorno('ok','Bancada salva','${b.ex.length?'Exames vinculados na ordem escolhida.':'Você poderá vincular esta bancada a outros exames depois.'}')">${c?'Salvar':'Cadastrar bancada'}</button>`}</div>`)}
function bcOff(c){const b=BANCADAS.find(x=>x.c===c);openModal(`${mh('Desativar '+b.n)}<div class="mb"><div class="alert warn"><span>Esta bancada tem <b>${b.ex.length} exames ativos</b>. A desativação fica bloqueada até realocar os exames.</span></div><div class="field"><label>Mover todos para…</label><select class="in">${BANCADAS.filter(x=>x.ativo&&x.c!==c).map(x=>`<option>${x.n}</option>`).join('')}</select></div><p class="tl">Amostras pendentes seguem para a bancada que recebeu os exames. Resultados e laudos já liberados não mudam.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn danger" onclick="closeModal();toast('Exames movidos e bancada desativada','warn')">Mover e desativar</button></div>`)}
