const PR_META={particular:{n:'Particular',sub:'cliente final · matriz',tipo:'Particular',vig:'01/10/2026',ver:3,por:'Sérgio',prox:'01/01/2027 (+6%)'},'Unimed Fortaleza':{n:'Unimed Fortaleza',sub:'convênio',tipo:'Convênio',vig:'01/07/2026',ver:5,por:'Sérgio'},Hapvida:{n:'Hapvida',sub:'convênio',tipo:'Convênio',vig:'01/07/2026',ver:4,por:'Sérgio'},'Plano DeoVita':{n:'Plano DeoVita',sub:'assinatura',tipo:'Convênio',vig:'01/03/2026',ver:2,por:'Jânio'},posto14:{n:'Posto 14 (repasse)',sub:'o que a matriz cobra do Posto 14 · Aldeota',tipo:'Posto',vig:'01/10/2026',ver:3,por:'Sérgio'},posto12:{n:'Posto 12 (repasse)',sub:'o que a matriz cobra do Posto 12 · Messejana',tipo:'Posto',vig:'01/10/2026',ver:3,por:'Sérgio'},'Mineradora Vale Verde':{n:'Mineradora Vale Verde',sub:'empresa · saúde ocupacional',tipo:'Empresa',vig:'01/02/2026',ver:1,por:'Sérgio'}};
/* padroes.js (TABS_PRECO, precoDe) carrega depois deste arquivo: a tabela da empresa entra na primeira abertura da tela. */
const prTabelas=()=>{if(!TABS_PRECO.some(([t])=>t==='Mineradora Vale Verde')){TABS_PRECO.push(['Mineradora Vale Verde','Mineradora Vale Verde · empresa']);TAB_CONV['Mineradora Vale Verde']=0.75}return TABS_PRECO.map(([id,n])=>Object.assign({id,n:n.split(' ·')[0],sub:'',tipo:'Convênio',vig:'01/10/2026',ver:1,por:'Sérgio'},PR_META[id]||{}))};
const prNome=id=>(PR_META[id]||{}).n||id;
let PR_TAB='todas';
const PR_TIP={Particular:'Preço ao paciente que paga do próprio bolso na matriz.',Convênio:'Preço de tabela negociado com o convênio; o paciente não paga.',Posto:'Repasse: o que a matriz cobra do posto por exame. O posto cobra do paciente pela tabela dele; a diferença é o lucro do posto.',Empresa:'Preço contratado com a empresa (saúde ocupacional, admissionais), faturado no fim do mês.'};
const prPrej=c=>{const k=precoDe(c,'custo');return prTabelas().filter(t=>precoDe(c,t.id)<k)};
const prBaixa=c=>{const k=precoDe(c,'custo');return prTabelas().filter(t=>{const p=precoDe(c,t.id);return p>=k&&margemDe(p,k)<20})};
VIEWS.precos=()=>{const ts=prTabelas(),t=ts.find(x=>x.id===PR_TAB);
 return `${pageHead('Financeiro','Tabelas de preço','Uma tabela por vez para trabalhar nela, ou todas lado a lado para comparar; cada tabela tem versões por data de vigência. Dados de exemplo.',`${rulesBtn('Tabelas de preço')}<button class="btn sec" onclick="toast('Importação por planilha com de→para e prévia antes e depois')">Importar planilha</button><button class="btn" onclick="prNova()" ${tipAttr('Nova tabela','Nome, tipo (convênio, posto, particular, empresa) e de onde copiar os preços, com ajuste em %.')}>${I.plus} Nova tabela</button>`)}
<div class="pr-tabs"><span class="lab" style="font-size:12px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--fg2)">Tabela</span><select class="in" style="width:auto" aria-label="Tabela" onchange="PR_TAB=this.value;reView()" ${tipAttr('Tabela','Escolha uma tabela para abrir só ela e editar os preços, ou "Todas" para comparar lado a lado (a lista rola para o lado; Exame e Custo ficam fixos).')}><option value="todas" ${PR_TAB==='todas'?'selected':''}>Todas as tabelas · comparar (${ts.length})</option>${ts.map(x=>`<option value="${esc(x.id)}" ${PR_TAB===x.id?'selected':''}>${esc(x.n)} · ${x.tipo.toLowerCase()}</option>`).join('')}</select>${PR_TAB==='todas'?`<span class="tl">${ts.length} tabelas · custo do exame vem do cadastro (matriz)</span>`:''}</div>
${t?`<div class="card pr-head"><div class="pr-meta"><b>${esc(t.n)} <span class="badge neutral" style="height:22px;font-size:11px">${t.tipo}</span></b><small>${esc(t.sub||'')}${t.sub?' · ':''}versão ${t.ver} · vigente desde ${t.vig} · criada por ${t.por}${t.prox?' · próxima: '+t.prox:''}</small></div><div class="row"><button class="btn sm sec" onclick="prReajuste('${esc(t.id)}')" ${tipAttr('Reajustar %','Percentual sobre toda a tabela ou um grupo de exames; cria versão nova com data de início.')}>Reajustar %</button><button class="btn sm sec" onclick="toast('Tabela ${esc(t.n)} exportada em Excel (versão ${t.ver})')" ${tipAttr('Exportar','Excel ou CSV com código, nome, TUSS e preço da versão vigente.')}>Exportar</button><button class="btn sm sec" onclick="prHist('${esc(t.id)}')" ${tipAttr('Histórico de versões','Todas as versões desta tabela, com data, quem criou e o que mudou.')}>Histórico de versões</button><button class="btn sm" onclick="retorno('ok','Versão nova criada','Versão ${t.ver+1} de ${esc(t.n)} criada a partir da vigente, com quem e quando. Os preços editados abaixo entram nela.')" ${tipAttr('Nova versão','Cada tabela tem versões com data de início; o atendimento usa a vigente e guarda o preço cobrado.')}>${I.plus} Nova versão</button></div></div>`:''}
${filtroBarra({id:'pr',busca:'Exame (nome, código ou sinônimo)',bancada:true,situacao:[['prej','Em prejuízo'],['baixa','Margem baixa'],['ok','Margem ok'],['sem','Sem preço']],onchange:'reView()',oninput:"filtroSet('pr','q',this.value);document.querySelector('#prBody').innerHTML=prLinhas()"})}
<div class="pr-wrap"><table class="at-table"><thead><tr><th ${tipAttr('Exame','Nome, código e sinônimos. Clique na linha para ajustar custo e preços em todas as tabelas.')}>Exame</th><th ${tipAttr('Custo (matriz)','Custo do exame no cadastro (reagente, apoio ou rateio). É a base da margem de todas as tabelas.')}>Custo</th>${PR_TAB==='todas'?ts.map(x=>`<th ${tipAttr(x.n,(PR_TIP[x.tipo]||'')+' Abaixo do preço, a margem sobre o custo.')}>${esc(x.n)}</th>`).join('')+`<th ${tipAttr('Margem','Resumo das tabelas ao lado: PREJUÍZO quando algum preço está abaixo do custo; MARGEM BAIXA quando alguma margem fica abaixo de 20% (as tabelas aparecem embaixo); ok quando todas estão acima.')}>Margem</th>`:`<th ${tipAttr('Preço nesta tabela','Edite direto na célula; a mudança entra na versão nova ao salvar.')}>Preço · ${esc(t.n)}</th><th ${tipAttr('Margem','Margem desta tabela sobre o custo: abaixo de 20% pisca em amarelo; abaixo do custo pisca em vermelho (prejuízo). Clique para ajustar.')}>Margem</th>`}</tr></thead><tbody id="prBody">${prLinhas()}</tbody></table></div>
<p class="tl" style="margin-top:8px">Exame sem preço não pode ser pedido na unidade, com aviso. O posto edita a tabela ao paciente dele; o central edita o repasse; permissões separadas. Clique na linha para corrigir custo e preços do exame em todas as tabelas de uma vez.</p>
${piada(34,{financeiro:'Reajuste em lote de 6%: a planilha chora, o posto reclama, o paciente nem percebe. Quase.',gestor:'O posto edita o preço ao paciente. O repasse quem edita é o central. Diplomacia em forma de permissão.',todos:'Tabela com versão por data: até o preço do hemograma tem passado, presente e futuro.'})}`};
function prLinhas(){const f=FILTROS.pr||{};const q=semAc(f.q||'');const ts=prTabelas(),one=PR_TAB!=='todas'?PR_TAB:null;
 const l=EXAMES.filter(e=>!e.serv).filter(e=>{if(q&&!semAc(e.n+' '+e.c+' '+(e.s||'')).includes(q))return false;if(f.bancada&&!(BANCADAS.find(b=>b.n===f.bancada)||{ex:[]}).ex.includes(e.c))return false;const k=precoDe(e.c,'custo');let prej,bx;if(one){const p=precoDe(e.c,one);prej=p<k;bx=!prej&&margemDe(p,k)<20}else{prej=prPrej(e.c).length>0;bx=!prej&&prBaixa(e.c).length>0}if(f.situacao==='prej')return prej;if(f.situacao==='baixa')return bx;if(f.situacao==='ok')return !prej&&!bx;if(f.situacao==='sem')return false;return true}).slice(0,16);
 const cols=one?4:ts.length+3;if(!l.length)return vazioLinha(cols,'Nenhum exame com estes filtros','Mude a busca ou os filtros.');
 const exame=e=>`<div class="two" title="${esc(e.n)} · código ${e.c}${e.s?' · sinônimos: '+esc(e.s):''}">${esc(e.n)}<small><span class="mono">${e.c}</span>${e.semTuss?' · sem TUSS':''}</small>${e.s?`<span class="pr-sin">sinônimos: ${esc(e.s)}</span>`:''}</div>`;
 return l.map(e=>{const k=precoDe(e.c,'custo');const cel=t=>`${fmt(precoDe(e.c,t))}<br>${margemTag(e.c,t)}`;
  if(one)return `<tr class="clk" onclick="exameMargem('${e.c}')" title="Clique para ajustar custo e preços deste exame em todas as tabelas">${td('Exame',exame(e))}${td('Custo',fmt(k))}${td('Preço',`<input class="in pr-in" value="${precoDe(e.c,one).toFixed(2).replace('.',',')}" aria-label="Preço de ${esc(e.n)}" onclick="event.stopPropagation()" onchange="prSetPreco('${e.c}','${esc(one)}',this.value)">`)}${td('Margem',margemTag(e.c,one))}</tr>`;
  const prej=prPrej(e.c),bx=prBaixa(e.c);
  return `<tr class="clk" onclick="exameMargem('${e.c}')" title="Clique para ajustar custo e preços deste exame em todas as tabelas">${td('Exame',exame(e))}${td('Custo',fmt(k))}${ts.map(t=>td(t.n,cel(t.id))).join('')}${td('Margem',prej.length?`<span class="badge err pisca" ${tipAttr('Prejuízo','Abaixo do custo em: '+prej.map(t=>t.n).join('; '))}>PREJUÍZO</span><small class="tl sub-tab">${prej.map(t=>t.n).join(', ')}</small>`:bx.length?`<span class="mg baixa pisca" ${tipAttr('Margem baixa','Abaixo de 20% em: '+bx.map(t=>t.n).join(', ')+'. Clique na linha para ajustar.')}>MARGEM BAIXA</span><small class="tl sub-tab">${bx.map(t=>t.n).join(', ')}</small>`:`<span class="mg ok">ok</span>`)}</tr>`}).join('')}
function prSetPreco(c,tab,v){const n=parseFloat(String(v).replace(/\./g,'').replace(',','.'));if(isNaN(n)||n<0){toast('Digite um valor válido','warn');reView();return}(PRECOS[c]=PRECOS[c]||{})[tab]=n;if(tab==='particular')EX[c].p=n;if(tab==='posto14')TAB_POSTO[c]=n;const k=precoDe(c,'custo');toast(n<k?'Preço abaixo do custo: '+EX[c].n+' fica em prejuízo nesta tabela':'Preço de '+EX[c].n+' alterado; entra na versão nova ao salvar',n<k?'warn':'ok');document.querySelector('#prBody').innerHTML=prLinhas()}
function prReajuste(id){const t=prTabelas().find(x=>x.id===id)||prTabelas()[0];openModal(`${mh('Reajustar · '+esc(t.n))}<div class="mb"><div class="formgrid"><div class="field"><label>Tabela</label><input class="in" value="${esc(t.n)}" disabled></div><div class="field"><label>Percentual</label><input class="in" value="6,0 %"></div><div class="field"><label>Grupo de exames</label><select class="in"><option>Todos</option>${BANCADAS.filter(b=>b.ativo).map(b=>`<option>${b.n}</option>`).join('')}</select></div><div class="field"><label>Vigência a partir de</label><input class="in" type="date" value="2027-01-01"></div></div><p class="tl">Cria a versão ${t.ver+1}; a atual continua valendo até a data.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Versão criada','Reajuste de 6% em ${esc(t.n)} a partir de 01/01/2027, com prévia aplicada a ${EXAMES.filter(e=>!e.serv).length} exames.')">Aplicar</button></div>`)}
function prHist(id){const t=prTabelas().find(x=>x.id===id);const vs=[];for(let v=t.ver;v>=1;v--)vs.push([v,v===t.ver?t.vig:v===t.ver-1?'01/01/2026':'15/03/2025',v===t.ver?t.por:'Sérgio',v===t.ver?'reajuste de 6% em todos os exames':v===1?'tabela criada'+(t.tipo==='Posto'?' a partir da Particular com −45%':'')  :'ajuste de 12 exames de bioquímica']);
 openModal(`${mh('Histórico de versões · '+esc(t.n))}<div class="mb">${tabela(['Versão','Vigência','Criada por','O que mudou',''],vs.map(([v,d,p,o])=>`<tr>${td('Versão',`<b>v${v}</b>${v===t.ver?' <span class="badge ok">vigente</span>':''}`)}${td('Vigência','desde '+d)}${td('Criada por',p)}${td('O que mudou',o)}${td('',`<button class="btn sm ghost" onclick="toast('Versão ${v} de ${esc(t.n)} aberta só para leitura')">Ver</button>`)}</tr>`))}<p class="tl" style="margin-top:8px">O atendimento guarda o preço cobrado na hora; trocar de versão nunca altera atendimentos antigos.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button></div>`)}
function prNova(){const ts=prTabelas();openModal(`${mh('Nova tabela de preço')}<div class="mb"><div class="formgrid"><div class="field"><label>Nome <span class="req">*</span></label><input class="in" id="ntNome" placeholder="Ex.: Bradesco Saúde, Posto 15, Clínica Vida Plena"></div><div class="field"><label>Tipo <span class="req">*</span> ${info('Convênio (preço de tabela do plano), Posto (repasse que a matriz cobra do posto), Particular (preço ao paciente numa unidade) ou Empresa (contrato faturado no mês).')}</label><select class="in" id="ntTipo"><option>Convênio</option><option>Posto</option><option>Particular</option><option>Empresa</option></select></div><div class="field"><label>Copiar preços de ${info('A nova tabela nasce com os preços desta, ajustados pelo percentual; depois você edita exame a exame.')}</label><select class="in" id="ntBase">${ts.map(t=>`<option value="${esc(t.id)}">${esc(t.n)}</option>`).join('')}</select></div><div class="field"><label>Ajuste sobre a base (%)</label><input class="in" id="ntPct" value="0" placeholder="Ex.: -10 para 10% abaixo"></div><div class="field"><label>Vigência a partir de</label><input class="in" type="date" value="2026-11-01" id="ntVig"></div></div><p class="tl">A tabela entra na lista do seletor e no quadro "Todas", e passa a contar na coluna Margem.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="prNovaOk()">Criar tabela</button></div>`)}
function prNovaOk(){const n=$('#ntNome').value.trim(),tipo=$('#ntTipo').value,base=$('#ntBase').value,pct=parseFloat(String($('#ntPct').value).replace(',','.'))||0,vig=$('#ntVig').value;if(!n){toast('Dê um nome à tabela','warn');$('#ntNome').focus();return}if(TABS_PRECO.some(([t])=>t===n)){toast('Já existe uma tabela com esse nome','warn');return}
 TABS_PRECO.push([n,n+' · '+tipo.toLowerCase()]);PR_META[n]={n,sub:tipo.toLowerCase()+' · copiada de '+prNome(base)+(pct?' com '+(pct>0?'+':'')+pct+'%':''),tipo,vig:vig?vig.split('-').reverse().join('/'):'hoje',ver:1,por:nomePerfil(PERFIL)};
 EXAMES.filter(e=>!e.serv).forEach(e=>{(PRECOS[e.c]=PRECOS[e.c]||{})[n]=Math.round(precoDe(e.c,base)*(1+pct/100)*100)/100});PR_TAB=n;closeModal();retorno('ok','Tabela criada','“'+n+'” nasceu com os preços de '+prNome(base)+(pct?' ajustados em '+pct+'%':'')+'. Ela já está aberta para você editar exame a exame.');reView()}
REGRAS['Tabelas de preço']=REGRAS['Tabelas de preço']||{aba:'Tabelas de preço',itens:[]};REGRAS['Tabelas de preço'].itens.push(['30/10','Uma tabela por vez (editar) ou todas lado a lado (comparar) com Exame e Custo fixos; as tabelas de repasse dos postos são colunas com o nome "(repasse)"; a coluna Margem cita só tabelas que estão na tela.']);

/* ===== Editar paciente (30/10, anotação 110): o botão Editar da gaveta só avisava; agora abre a ficha preenchida e salva ===== */
function pacEditar(cpf){const p=PACIENTES.find(x=>x.cpf===cpf);if(!p)return;const end=p.end||{};const podeCpf=PERFIL==='admin';
 openModal(`${mh('Editar paciente · '+esc(p.n))}<div class="mb"><h4>Identificação</h4><div class="formgrid"><div class="field"><label>Nome completo <span class="req">*</span></label><input class="in" id="peN" value="${esc(p.n)}"></div><div class="field"><label>CPF ${info(podeCpf?'Administrador pode corrigir o CPF; a troca fica na auditoria e checa duplicado.':'Só o administrador altera o CPF (identificação única do paciente).')}</label><input class="in" id="peCpf" value="${p.cpf}" ${podeCpf?'':'disabled'} oninput="this.value=mCPF(this.value)"></div><div class="field"><label>Nascimento <span class="req">*</span></label><input class="in" type="date" id="peDn" value="${p.dn}"></div><div class="field"><label>Sexo <span class="req">*</span> ${info('Define as faixas de referência; sexo biológico, como no cadastro do componente.')}</label><select class="in" id="peSx"><option value="F" ${p.sx==='F'?'selected':''}>Feminino</option><option value="M" ${p.sx==='M'?'selected':''}>Masculino</option></select></div><div class="field"><label>Nome social</label><input class="in" id="peSoc" value="${esc(p.soc||'')}" placeholder="Como prefere ser chamado(a)"></div><div class="field"><label>Nome da mãe ${info('Segunda identificação, usada na dupla checagem da coleta.')}</label><input class="in" id="peMae" value="${esc(p.mae||'')}"></div><div class="field"><label>Responsável ${info('Obrigatório para menor de 18 anos; nome e telefone.')}</label><input class="in" id="peResp" value="${esc(p.resp||'')}"></div></div>
<h4 style="margin-top:12px">Contato e endereço</h4><div class="formgrid"><div class="field"><label>Telefone / WhatsApp <span class="req">*</span></label><input class="in" id="peTel" value="${esc(p.tel)}" oninput="this.value=mTel(this.value)"></div><div class="field"><label>E-mail</label><input class="in" id="peEm" value="${esc(p.email||'')}"></div><div class="field"><label>CEP</label><input class="in" id="peCep" value="${esc(end.cep||'')}" placeholder="00000-000"></div><div class="field" style="grid-column:span 2"><label>Endereço</label><input class="in" id="peRua" value="${esc(end.rua||'')}" placeholder="Rua, número, complemento"></div><div class="field"><label>Bairro</label><input class="in" id="peBai" value="${esc(end.bairro||'')}"></div><div class="field"><label>Cidade · UF</label><input class="in" id="peCid" value="${esc(end.cid||'Fortaleza · CE')}"></div></div>
<h4 style="margin-top:12px">Convênio e observações</h4><div class="formgrid"><div class="field"><label>Convênio padrão</label><select class="in" id="peConv"><option>Particular</option>${CONVENIOS.map(c=>`<option ${p.conv===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Carteirinha</label><input class="in" id="peCart" value="${esc(p.cart||'')}"></div><div class="field" style="grid-column:1/-1"><label>Observações ${info('Visíveis na recepção e na coleta: acesso difícil, prefere box 2, medo de agulha...')}</label><textarea class="in" id="peObs" rows="2">${esc(p.obs||'')}</textarea></div></div>
<h4 style="margin-top:12px">Consentimento (LGPD) ${info('O termo vigente é a versão 2; cada aceite fica com data, canal e versão na rastreabilidade.')}</h4><div class="row"><label class="check"><input type="checkbox" id="peWa" ${p.okWa!==false?'checked':''}>Aviso de resultado por WhatsApp</label><label class="check"><input type="checkbox" id="peEmOk" ${p.okEm?'checked':''}>Aviso por e-mail</label><label class="check"><input type="checkbox" id="peSms" ${p.okSms?'checked':''}>Aviso por SMS</label><label class="check"><input type="checkbox" id="pePesq" ${p.okPesq!==false?'checked':''}>Pesquisa de satisfação</label></div>
<p class="tl" style="margin-top:8px">Toda alteração fica na aba Rastreabilidade com quem, quando e o valor anterior.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal();pacFicha('${cpf}')">Cancelar</button><button class="btn" onclick="pacEditarOk('${cpf}')">Salvar alterações</button></div>`,'wide')}
function pacEditarOk(cpf){const p=PACIENTES.find(x=>x.cpf===cpf);if(!p)return;const n=$('#peN').value.trim(),dn=$('#peDn').value,tel=$('#peTel').value.trim();if(!n||!dn||!tel){toast('Nome, nascimento e telefone são obrigatórios','warn');return}
 const novoCpf=$('#peCpf').disabled?p.cpf:mCPF($('#peCpf').value);if(novoCpf!==p.cpf&&PACIENTES.some(x=>x.cpf===novoCpf)){toast('Já existe paciente com este CPF: use "Unificar" em Opções','warn');return}
 const mudou=[];if(n!==p.n)mudou.push('nome');if(tel!==p.tel)mudou.push('telefone');if(dn!==p.dn)mudou.push('nascimento');
 Object.assign(p,{cpf:novoCpf,n,dn,sx:$('#peSx').value,soc:$('#peSoc').value.trim(),mae:$('#peMae').value.trim(),resp:$('#peResp').value.trim(),tel,email:$('#peEm').value.trim(),end:{cep:$('#peCep').value.trim(),rua:$('#peRua').value.trim(),bairro:$('#peBai').value.trim(),cid:$('#peCid').value.trim()},conv:$('#peConv').value,cart:$('#peCart').value.trim(),obs:$('#peObs').value.trim(),okWa:$('#peWa').checked,okEm:$('#peEmOk').checked,okSms:$('#peSms').checked,okPesq:$('#pePesq').checked});
 closeModal();toast('Paciente salvo'+(mudou.length?' · alterado: '+mudou.join(', '):'')+' · registrado na auditoria');if(typeof reView==='function')reView();pacFicha(p.cpf)}
